202	/**
203	 * Persist a failed notification send so the failure is not silent.
204	 *
205	 * The notification channel (email) is the thing that broke, so we can't email
206	 * the user to tell them email failed. Instead we record it in
207	 * `email_send_failures`: the row is family-scoped (RLS) so the user sees an
208	 * in-app notice, and it doubles as the admin alert feed. Best-effort — a
209	 * logging failure must never break webhook processing.
210	 */
211	async function recordNotificationFailure(
212		supabase: SupabaseClient,
213		params: {
214			userId: string;
215			recipient: string;
216			notificationType: NotificationType;
217			originalSubject: string;
218			emailId?: string;
219			statusCode: number;
220			error: string;
221		}
222	): Promise<void> {
223		try {
224			const { error } = await supabase.from('email_send_failures').insert({
225				user_id: params.userId,
226				recipient: params.recipient,
227				notification_type: params.notificationType,
228				original_subject: params.originalSubject,
229				resend_email_id: params.emailId ?? null,
230				status_code: params.statusCode,
231				error: params.error
232			});
233			if (error) {
234				console.error('Failed to record notification failure:', JSON.stringify(error));
235			} else {
236				console.log(`Recorded notification failure for ${params.recipient} (admin alert queued)`);
237			}
238		} catch (err) {
239			console.error('Exception recording notification failure:', err);
240		}
241	}
242	
243	/**
244	 * Send a notification email and, if the send fails, record it durably so the
245	 * failure surfaces to the user (in-app) and to admins instead of vanishing into
246	 * the logs. Wraps the extracted `sendResendNotification` sender.
247	 */
248	async function sendNotificationEmail(
249		supabase: SupabaseClient,
250		userId: string,
251		apiKey: string,
252		toEmail: string,
253		notificationType: NotificationType,
254		title: string,
255		message: string,
256		originalSubject: string,
257		emailId?: string
258	): Promise<void> {
259		const result = await sendResendNotification(
260			apiKey,
261			toEmail,
262			notificationType,
263			title,
264			message,
265			originalSubject,
266			emailId
267		);
268	
269		if (!result.ok) {
270			await recordNotificationFailure(supabase, {
271				userId,
272				recipient: toEmail,
273				notificationType,
274				originalSubject,
275				emailId,
276				statusCode: result.status,
277				error: result.error ?? 'Unknown send failure'
278			});
279		}
280	}
281	
282	Deno.serve(async (req) => {
283		console.log('=== Resend Webhook Request Received ===');
284		console.log('Method:', req.method);
285		console.log('URL:', req.url);
286	
287		if (req.method !== 'POST') {
288			console.log('Rejecting non-POST request');
289			return jsonResponse(405, { error: 'Method not allowed' });
290		}
291	
292		// Read the raw body for signature verification
293		const bodyText = await req.text();
294		console.log('Received webhook payload length:', bodyText.length);
295		console.log('Raw payload:', bodyText.substring(0, 500) + (bodyText.length > 500 ? '...' : ''));
296	
297		let event: ResendWebhookEvent;
298	
299		try {
300			event = JSON.parse(bodyText);
301			console.log('Parsed event type:', event.type);
302			console.log('Event data:', JSON.stringify(event.data));
303		} catch (e) {
304			console.error('Failed to parse JSON:', e);
305			return jsonResponse(400, { error: 'Invalid JSON' });
306		}
307	
308		// Basic validation
309		if (!event.type) {
310			console.error('Missing event type in payload');
311			return jsonResponse(400, { error: 'Missing event type' });
312		}
313	
314		const supabaseUrl = Deno.env.get('SUPABASE_URL');
315		const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
316		const resendApiKey = Deno.env.get('RESEND_API_KEY');
317		const resendWebhookSecret = Deno.env.get('RESEND_WEBHOOK_SECRET');
318	
319		if (!supabaseUrl || !serviceRoleKey) {
320			return jsonResponse(500, { error: 'Missing Supabase env' });
321		}
322		if (!resendApiKey) {
323			console.error('RESEND_API_KEY environment variable is not set');
324			return jsonResponse(500, { error: 'Missing Resend API key' });
325		}
326	
327		console.log(`Resend API key is set (length: ${resendApiKey.length})`);
328	
329		// Log all request headers for debugging
330		console.log('Request headers:', JSON.stringify(Object.fromEntries(req.headers.entries())));
331	
332		// Verify the webhook signature — FAIL CLOSED. This endpoint runs with the
333		// service role and inserts receipts keyed on the sender's email, so an
334		// unauthenticated caller could forge an `email.received` event and inject
335		// receipts into any user's account (bypassing RLS). A missing secret is a
336		// server misconfiguration (500); a bad/absent signature is rejected (401).
337		// Never log the secret value.
338		if (!resendWebhookSecret) {
339			console.error('RESEND_WEBHOOK_SECRET is not set — refusing to process unverified webhook');
340			return jsonResponse(500, { error: 'Webhook signing secret not configured' });
341		}
342		if (!verifyWebhookSignature(req.headers, bodyText, resendWebhookSecret)) {
343			console.error('Invalid webhook signature — rejecting request');
344			return jsonResponse(401, { error: 'Invalid webhook signature' });
345		}
346		console.log('Webhook signature verification passed');
347	
348		// Only process email.received events
349		if (event.type !== 'email.received') {
350			console.log(`Ignoring event type: ${event.type} - returning success`);
351			return jsonResponse(200, { message: `Event type ${event.type} ignored` });
352		}
353	
354		console.log('Processing email.received event...');
355	
356		const supabase = createServiceClient(supabaseUrl, serviceRoleKey);
357	
358		// Find user by sender email. Resend delivers `from` as either a bare address
359		// or `Display Name <addr>` — extract the address so the exact-match lookup
360		// works regardless of the forwarding client's formatting.
361		const sender = parseSenderEmail(event.data?.from);
362		if (!sender) {
363			console.error('Missing or unparseable sender in event data:', event.data?.from);
364			return jsonResponse(400, { error: 'Missing sender' });
365		}
366	
367		console.log(`Looking up user by email: ${sender}`);
368		const { data: userIdData, error: userErr } = await supabase.rpc('find_user_by_email', {
369			email_address: sender
370		});
371		if (userErr) {
372			console.error(`Error finding user: ${JSON.stringify(userErr)}`);
373			return jsonResponse(500, { error: userErr.message });
374		}
375		if (!userIdData) {
376			console.error(`No user found for email: ${sender}`);
377			return jsonResponse(404, { error: 'User not found for sender email' });
378		}
379		const userId = userIdData as string;
380		console.log(`Found user ID: ${userId}`);
381	
382		// Fetch the full email content from Resend API to get body text
383		console.log(`Fetching email content for email_id: ${event.data.email_id}`);
384		console.log(
385			`Using API key: ${resendApiKey.substring(0, 7)}...${resendApiKey.substring(resendApiKey.length - 4)}`
386		);
387		console.log(`API endpoint: https://api.resend.com/emails/receiving/${event.data.email_id}`);
388	
389		let emailBodyText = '';
390	
391		try {
392			const emailResponse = await fetch(
393				`https://api.resend.com/emails/receiving/${event.data.email_id}`,
394				{
395					method: 'GET',
396					headers: {
397						Authorization: `Bearer ${resendApiKey}`,
398						'Content-Type': 'application/json'
399					}
400				}
401			);
402	
403			console.log(`Email fetch response status: ${emailResponse.status}`);
404	
405			if (!emailResponse.ok) {
406				const errorText = await emailResponse.text();
407				console.error(`Failed to fetch email: ${emailResponse.status} ${emailResponse.statusText}`);
408				console.error(`Error response body: ${errorText}`);
409				// Don't return error - continue with attachments processing
410			} else {
411				const email: ResendEmail = await emailResponse.json();
412				console.log(
413					`Email fetched successfully. Has text: ${!!email.text}, Has html: ${!!email.html}`
414				);
415				emailBodyText = (email.text || email.html || '').toString();
416			}
417		} catch (e) {
418			console.error('Exception fetching email content:', e);
419			// Continue processing - we can still try attachments
420		}
421	
422		// #{#eaf5a} Check for supported attachments before processing body text
423		const attachmentMetadata = event.data.attachments || [];
424		const hasScannable = hasSupportedAttachments(attachmentMetadata);
425	
426		let inserted: InsertedReceipt | null = null;
427		const processingErrors: string[] = [];
428	
429		// #{#eaf5a} Only process body text if no supported attachments exist
430		if (emailBodyText && !hasScannable) {
431			console.log('No supported attachments found, processing email body text');
432		} else if (hasScannable) {
433			console.log(
434				`Skipping body text extraction — ${attachmentMetadata.length} supported attachment(s) found`
435			);
436		}
437	
438		if (emailBodyText && !hasScannable) {
439			try {
440				console.log('Processing email body text with Mistral...');
441				const extracted = await processEmailText(emailBodyText);
442	
443				if (extracted) {
444					console.log('Mistral found receipt data:', JSON.stringify(extracted, null, 2));
445	
446					// Convert the text to an image
447					console.log('Converting text to image...');
448					const imageBytes = await textToImage(emailBodyText);
449					const { path, signedUrl } = await uploadToStorage(
450						supabase,
451						userId,
452						imageBytes,
453						'image/svg+xml',
454						'svg'
455					);
456					console.log('Image uploaded to:', signedUrl);
457	
458					// Insert receipt with the text-as-image
459					try {
460						console.log('Inserting receipt for user:', userId);
461	
462						// #{#rdc4c} #{#rdc5a} Correct the OCR date from the verbatim raw string, then
463						// flag suspicious dates (#{#dtv4a}). Uncorrectable wrong-token reads are flagged.
464						const resolved = resolveOcrReceiptDate(
465							extracted.transaction_date ?? null,
466							extracted.raw_date_text ?? null,
467							new Date()
468						);
469						extracted.transaction_date = resolved.transaction_date;
470						const suspicious = resolved.suspicious_date;
471						if (suspicious) {
472							console.log(
473								`Warning: Suspicious date detected for email receipt: ${extracted.transaction_date}`
474							);
475	
476							// Notify user about suspicious date
477							await sendNotificationEmail(
478								supabase,
479								userId,
480								resendApiKey,
481								sender,
482								'warning',
483								'Please Check Receipt Date',
484								`The receipt date we found (${extracted.transaction_date}) seems unusual - it's either more than 6 weeks old or in the future. We've saved the receipt, but please verify the date is correct and update it if needed.`,
485								event.data.subject,
486								event.data.email_id
487							);
488						}
489	
490						// #{#fcr1a} #{#fcr2a} Fetch exchange rate for foreign currency receipts
491						const exchangeRate = await fetchRateForReceipt(
492							extracted.currency,
493							extracted.transaction_date
494						);
495	
496						inserted = await insertReceipt(supabase, {
497							user_id: userId,
498							receipt_image_path: path,
499							merchant_name: extracted.merchant_name,
500							total_amount: extracted.total_amount,
501							tax: extracted.tax,
502							transaction_date: extracted.transaction_date,
503							currency: extracted.currency,
504							exchange_rate_to_cad: exchangeRate,
505							credit_card_name: extracted.credit_card_name,
506							credit_card_last_4: extracted.credit_card_last_4,
507							suspicious_date: suspicious
508						});
509						console.log('Receipt inserted successfully:', inserted?.id);
510					} catch (insertErr) {
511						const msg = `Body text insert failed: ${errText(insertErr)}`;
512						console.error(msg);
513						processingErrors.push(msg);
514					}
515				} else {
516					console.log('No receipt data found in email body text');
517					// Don't send notification yet - we'll try attachments first
518				}
519			} catch (e) {
520				const msg = `Body text processing error: ${errText(e)}`;
521				console.error(msg);
522				processingErrors.push(msg);
523			}
524		}
525	
526		// Process attachments (either as primary path or fallback from body text)
527		if (!inserted) {
528			console.log(`Found ${attachmentMetadata.length} attachment(s) in webhook payload`);
529	
530			if (attachmentMetadata.length === 0) {
531				console.log('No attachments to process');
532			} else {
533				// Fetch attachment download URLs from Resend API
534				console.log(`Fetching attachment download URLs for email_id: ${event.data.email_id}`);
535	
536				try {
537					const attachmentsResponse = await fetch(
538						`https://api.resend.com/emails/receiving/${event.data.email_id}/attachments`,
539						{
540							method: 'GET',
541							headers: {
542								Authorization: `Bearer ${resendApiKey}`,
543								'Content-Type': 'application/json'
544							}
545						}
546					);
547	
548					console.log(`Attachments fetch response status: ${attachmentsResponse.status}`);
549	
550					if (!attachmentsResponse.ok) {
551						const errorText = await attachmentsResponse.text();
552						const msg = `Resend attachment fetch failed: ${attachmentsResponse.status} ${attachmentsResponse.statusText} — ${errorText}`;
553						console.error(msg);
554						processingErrors.push(msg);
555					} else {
556						const attachmentsData = await attachmentsResponse.json();
557						console.log(`Attachments response data: ${JSON.stringify(attachmentsData)}`);
558						const attachments: ResendAttachment[] = attachmentsData.data || [];
559	
560						console.log(`Received ${attachments.length} attachment download URL(s)`);
561	
562						let processedCount = 0;
563	
564						for (const att of attachments) {
565							try {
566								// #{#eaf2a} Skip inline attachments (signatures, logos)
567								if (
568									isInlineAttachment({
569										filename: att.filename,
570										content_type: att.content_type,
571										content_id: att.content_id,
572										content_disposition: att.content_disposition
573									})
574								) {
575									console.log(
576										`Skipping inline attachment: ${att.filename} (content_id: ${att.content_id})`
577									);
578									continue;
579								}
580	
581								// #{#eaf1a} Filter by supported MIME types
582								const ct = att.content_type || 'application/octet-stream';
583								if (!isSupportedReceiptType(ct, att.filename)) {
584									console.log(`Skipping unsupported attachment type: ${ct} (${att.filename})`);
585									continue;
586								}
587	
588								console.log(`Processing attachment: ${att.filename}`);
589	
590								// Download attachment using the provided download_url
591								const downloadResponse = await fetch(att.download_url);
592								if (!downloadResponse.ok) {
593									const msg = `Download failed for ${att.filename}: HTTP ${downloadResponse.status}`;
594									console.error(msg);
595									processingErrors.push(msg);
596	
597									// Notify user about attachment download failure
598									await sendNotificationEmail(
599										supabase,
600										userId,
601										resendApiKey,
602										sender,
603										'error',
604										'Attachment Download Failed',
605										`We couldn't download the attachment "${att.filename}" from your email. Resend attachments expire after 30 minutes, so the download link may have expired. Please try forwarding the email again.`,
606										event.data.subject,
607										event.data.email_id
608									);
609	
610									continue;
611								}
612	
613								const bytes = new Uint8Array(await downloadResponse.arrayBuffer());
614								const ext = (att.filename?.split('.')?.pop() || 'bin').toLowerCase();
615	
616								const { path, signedUrl } = await uploadToStorage(supabase, userId, bytes, ct, ext);
617								const extracted = await ocrFromUrl(signedUrl, ct).catch(async (err) => {
618									const msg = `OCR failed for ${att.filename}: ${err?.message || err}`;
619									console.error(msg);
620									processingErrors.push(msg);
621	
622									// Notify user about OCR failure
623									await sendNotificationEmail(
624										supabase,
625										userId,
626										resendApiKey,
627										sender,
628										'error',
629										'Receipt Reading Failed',
