1	/**
2	 * Shared Receipt Date Parsing Correction (Edge Function copy)
3	 *
4	 * #{#rdc4c authority=developer} - Correction parity for the email/resend path
5	 *
6	 * Behavioural mirror of `src/lib/utils/receiptDateCorrection.ts`. Kept in lock-step with
7	 * that file; `receiptDateCorrection.spec.ts` asserts parity over the regression corpus so
8	 * the two copies cannot drift. Self-contained (inline local-date helpers) so it has no
9	 * dependency on the SvelteKit `$lib` aliases.
10	 *
11	 * Implements #{#rdc1a}, #{#rdc3a}, #{#rdc3b}, #{#rdc4a}, #{#rdc4b}, #{#rdc5a}.
12	 */
13	
14	import { isSuspiciousDate } from './dateValidation.ts';
15	
16	export const PLAUSIBILITY_WINDOW_DAYS = 90;
17	
18	const MS_PER_DAY = 1000 * 60 * 60 * 24;
19	
20	export type DateCorrectionResult = {
21		transaction_date: string | null;
22		corrected: boolean;
23		uncorrectable: boolean;
24	};
25	
26	/** Parse a YYYY-MM-DD string into a local-time Date (avoids UTC day shift). */
27	function toDate(iso: string | null | undefined): Date | undefined {
28		if (!iso) return undefined;
29		const parts = iso.split('-');
30		if (parts.length !== 3) return undefined;
31		const [y, m, d] = parts.map((p) => parseInt(p, 10));
32		if (Number.isNaN(y) || Number.isNaN(m) || Number.isNaN(d)) return undefined;
33		return new Date(y, m - 1, d);
34	}
35	
36	/** Format a Date as a local-time YYYY-MM-DD string. */
37	function toISODateString(date: Date): string {
38		const y = date.getFullYear();
39		const m = String(date.getMonth() + 1).padStart(2, '0');
40		const d = String(date.getDate()).padStart(2, '0');
41		return `${y}-${m}-${d}`;
42	}
43	
44	/** Calendar-day difference (uploadDate - candidate), DST-safe via UTC-normalized parts. */
45	function dayDelta(candidate: Date, uploadDate: Date): number {
46		const utcDay = (dt: Date) => Date.UTC(dt.getFullYear(), dt.getMonth(), dt.getDate());
47		return Math.round((utcDay(uploadDate) - utcDay(candidate)) / MS_PER_DAY);
48	}
49	
50	export function isPlausible(candidate: Date, uploadDate: Date): boolean {
51		const diffDays = dayDelta(candidate, uploadDate);
52		return diffDays >= 0 && diffDays <= PLAUSIBILITY_WINDOW_DAYS;
53	}
54	
55	function expandYear(token: string): number | null {
56		if (token.length === 4) return parseInt(token, 10);
57		if (token.length >= 1 && token.length <= 2) return 2000 + parseInt(token, 10);
58		return null;
59	}
60	
61	function buildDate(year: number | null, month: number, day: number): string | null {
62		if (year === null || !Number.isFinite(month) || !Number.isFinite(day)) return null;
63		const date = new Date(year, month - 1, day);
64		if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
65			return null;
66		}
67		return toISODateString(date);
68	}
69	
70	export function parseRawDate(rawDateText: string, uploadDate: Date): string[] {
71		const groups = rawDateText.split(/\D+/).filter((g) => g.length > 0);
72		if (groups.length < 3) return [];
73	
74		const [a, b, c] = groups;
75		const ai = parseInt(a, 10);
76		const bi = parseInt(b, 10);
77		const ci = parseInt(c, 10);
78	
79		const interpretations: Array<string | null> = [
80			a.length === 4 ? buildDate(parseInt(a, 10), bi, ci) : null, // YYYY/MM/DD
81			buildDate(expandYear(a), bi, ci), // YY/MM/DD (and YY-MM-DD)
82			buildDate(expandYear(c), ai, bi), // MM/DD/YY
83			buildDate(expandYear(c), bi, ai) // DD/MM/YY
84		];
85	
86		const seen = new Map<string, number>();
87		interpretations.forEach((iso, rank) => {
88			if (!iso) return;
89			const date = toDate(iso);
90			if (!date || !isPlausible(date, uploadDate)) return;
91			if (!seen.has(iso)) seen.set(iso, rank);
92		});
93	
94		return [...seen.entries()]
95			.sort((x, y) => {
96				const dx = dayDelta(toDate(x[0]) as Date, uploadDate);
97				const dy = dayDelta(toDate(y[0]) as Date, uploadDate);
98				if (dx !== dy) return dx - dy;
99				return x[1] - y[1];
100			})
101			.map((entry) => entry[0]);
102	}
103	
104	export function correctDate(
105		transactionDate: string | null,
106		rawDateText: string | null | undefined,
107		uploadDate: Date
108	): DateCorrectionResult {
109		const mistralDate = transactionDate && transactionDate.length > 0 ? transactionDate : null;
110	
111		if (mistralDate) {
112			const parsed = toDate(mistralDate);
113			if (parsed && isPlausible(parsed, uploadDate)) {
114				return { transaction_date: mistralDate, corrected: false, uncorrectable: false };
115			}
116		}
117	
118		const raw = rawDateText && rawDateText.trim().length > 0 ? rawDateText.trim() : null;
119		if (!raw) {
120			return { transaction_date: mistralDate, corrected: false, uncorrectable: false };
121		}
122	
123		const candidates = parseRawDate(raw, uploadDate);
124		if (candidates.length > 0) {
125			return { transaction_date: candidates[0], corrected: true, uncorrectable: false };
126		}
127	
128		return { transaction_date: mistralDate, corrected: false, uncorrectable: mistralDate !== null };
129	}
130	
131	export function resolveOcrReceiptDate(
132		transactionDate: string | null,
133		rawDateText: string | null | undefined,
134		uploadDate: Date
135	): { transaction_date: string | null; suspicious_date: boolean } {
136		const { transaction_date, uncorrectable } = correctDate(transactionDate, rawDateText, uploadDate);
137		return {
138			transaction_date,
139			suspicious_date: uncorrectable || isSuspiciousDate(transaction_date)
140		};
141	}
