11	// the interpreted `transaction_date`, so code can re-parse ambiguous formats (#{#rdc4a}).
12	export const receiptPrompt: string = `Extract fields from the receipt. Respond as JSON with keys: transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed on the receipt, verbatim — keep the original separators and digits, do not reinterpret), total_amount (number), tax (number), merchant_name (string), currency (ISO 4217), credit_card_name (string), credit_card_last_4 (string). Default currency to CAD unless the receipt explicitly states a different currency. A bare "$" sign means CAD.`;
13	
14	export type FileCategory = 'pdf' | 'image';
15	
16	export class OcrService {
17		private client: Mistral | null = null;
18	
19		/**
20		 * Initialize the Mistral client with API key from environment
21		 */
22		private async initClient(): Promise<Mistral> {
23			if (this.client) {
24				return this.client;
25			}
26	
27			// Use private environment variable (server-side only)
28			const { MISTRAL_API_KEY } = await import('$env/static/private');
29			if (!MISTRAL_API_KEY) {
30				throw new Error(
31					'MISTRAL_API_KEY environment variable is not set. Please configure it in your .env file.'
32				);
33			}
34	
35			this.client = new Mistral({ apiKey: MISTRAL_API_KEY });
36			return this.client;
37		}
38	
39		/**
40		 * Supported MIME types for OCR processing
41		 */
42		private static readonly SUPPORTED_TYPES = {
43			PDF: ['application/pdf'],
44			IMAGE: ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic', 'image/heif']
45		} as const;
46	
47		/**
48		 * Categorizes a MIME type into pdf or image
49		 */
50		private categorizeMimeType(mimeType: string): FileCategory | null {
51			// Normalize: remove parameters and convert to lowercase
52			const normalized = mimeType.split(';')[0].trim().toLowerCase();
53	
54			const pdfTypes: readonly string[] = OcrService.SUPPORTED_TYPES.PDF;
55			const imageTypes: readonly string[] = OcrService.SUPPORTED_TYPES.IMAGE;
56	
57			if (pdfTypes.includes(normalized)) {
58				return 'pdf';
59			}
60	
61			if (imageTypes.includes(normalized)) {
62				return 'image';
63			}
64	
65			return null;
66		}
67	
68		/**
69		 * Extracts receipt data from a URL (image or PDF)
70		 * Mistral's pixtral model handles both images and PDFs directly
71		 *
72		 * @param fileUrl - URL of the file to process
73		 * @param mimeType - MIME type of the file
74		 * @returns Extracted receipt data
75		 * @throws Error if validation fails or API call fails
76		 */
77		async extractFromUrl(fileUrl: string, mimeType: string): Promise<ReceiptExtract> {
78			try {
79				// Validate inputs
80				if (!fileUrl || typeof fileUrl !== 'string' || fileUrl.trim().length === 0) {
81					throw new Error('Invalid file URL provided');
82				}
83	
84				if (!mimeType || typeof mimeType !== 'string') {
85					throw new Error('MIME type is required');
86				}
87	
88				// Categorize and validate MIME type
89				const category = this.categorizeMimeType(mimeType);
90	
91				if (!category) {
92					const supported = [
93						...OcrService.SUPPORTED_TYPES.PDF,
94						...OcrService.SUPPORTED_TYPES.IMAGE
95					].join(', ');
96					throw new Error(`Unsupported file type: ${mimeType}. Supported types: ${supported}`);
97				}
98	
99				// Initialize client
100				const client = await this.initClient();
101	
102				console.log(`OcrService.extractFromUrl() processing ${category}: ${fileUrl}`);
103	
104				// Build request based on file category
105				const fileChunk: ContentChunk =
106					category === 'pdf'
107						? { type: 'document_url', documentUrl: fileUrl }
108						: { type: 'image_url', imageUrl: fileUrl };
109	
110				const maxRetries = 3;
111				let chatResponse;
112				for (let attempt = 1; attempt <= maxRetries; attempt++) {
113					chatResponse = await chatComplete(client, {
114						model: ocrModel,
115						responseFormat: { type: 'json_object' },
116						messages: [
117							{
118								role: 'user',
119								content: [{ type: 'text', text: receiptPrompt }, fileChunk]
120							}
121						]
122					});
123	
124					if (chatResponse?.ok) break;
125	
126					// Retry on transient errors (rate limiting, image fetch failures)
127					const errorStr = chatResponse ? String(chatResponse.error) : 'no response from Mistral SDK';
128					const isRetryable = errorStr.includes('400') || errorStr.includes('429');
129					if (!isRetryable || attempt === maxRetries) {
130						throw new Error(`Mistral OCR request failed: ${errorStr}`);
131					}
132					console.warn(`Mistral OCR attempt ${attempt} failed, retrying in ${attempt * 2}s...`);
133					await new Promise((r) => setTimeout(r, attempt * 2000));
134				}
135	
136				// Unreachable in practice (the loop breaks with an ok response or throws), but
137				// guards the compiler-visible undefined case the same soft way as every other
138				// OCR failure: callers in ocrProcessor catch this and return { success: false }.
139				if (!chatResponse?.ok) {
140					throw new Error('Mistral OCR request failed: no response from Mistral SDK');
141				}
142	
143				const completionResponse: ChatCompletionResponse = chatResponse.value;
144	
145				// Validate response structure
146				if (!completionResponse.choices || completionResponse.choices.length === 0) {
147					throw new Error('Mistral API returned no choices in response');
148				}
149	
150				const firstChoice = completionResponse.choices[0];
151				if (!firstChoice.message || !firstChoice.message.content) {
152					throw new Error('Mistral API returned empty message content');
153				}
154	
155				// Log all choices for debugging (using forEach instead of map)
156				completionResponse.choices.forEach((choice, index) => {
157					console.log(`Choice ${index}:`, choice.message.content);
158				});
159	
160				const jsonString = firstChoice.message.content as string;
161				const receipt = this.parseTransactionJson(jsonString);
162				return receipt;
163			} catch (error) {
164				// Re-throw with more context
165				const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
166				throw new Error(`OCR extraction failed: ${errorMessage}`);
167			}
168		}
169	
170		/**
171		 * Parses JSON response from Mistral API, handling markdown code blocks
172		 *
173		 * @param jsonString - Raw JSON string from API (may be wrapped in markdown)
174		 * @returns Parsed receipt extract object
175		 * @throws Error if parsing fails
176		 */
177		parseTransactionJson(jsonString: string): ReceiptExtract {
178			try {
179				if (!jsonString || typeof jsonString !== 'string') {
180					throw new Error('Invalid JSON string provided');
181				}
182	
183				let cleanedJson = jsonString.trim();
184	
185				// Remove markdown code block markers if present
186				// Handles variations: ```json, ```JSON, ``` with json, etc.
187				const codeBlockRegex = /^```(?:json|JSON)?\s*\n?([\s\S]*?)\n?```$/;
188				const match = cleanedJson.match(codeBlockRegex);
189	
190				if (match) {
191					cleanedJson = match[1].trim();
192				}
193	
194				// Parse the JSON
195				const parsedData = JSON.parse(cleanedJson);
196	
197				// Basic validation - ensure it's an object
198				if (!parsedData || typeof parsedData !== 'object' || Array.isArray(parsedData)) {
199					throw new Error('Parsed data is not a valid object');
200				}
201	
202				// Return with type assertion
203				// Note: Further validation should be done by the sanitizeExtract function
204				return parsedData as ReceiptExtract;
205			} catch (error) {
206				const errorMessage = error instanceof Error ? error.message : 'Unknown parsing error';
207				throw new Error(`Failed to parse transaction data: ${errorMessage}`);
208			}
209		}
210	}
